import {
  VerticalHeaderLogoTitle,
  VerticalHeaderLogoTitleName,
} from "../../../../components/layout/main/header";
import { AnimatedImage } from "../../../../components/images";
import { useVideoDataContext } from "../../../../core/context/VideoDataContext";
import { useThemeContext } from "../../../../core/context/ThemeContext";
import { useAnimationContext } from "../../../../core/context/AnimationContext";
import { calculateMainHeaderExitFrame } from "../../../../core/timing/mainSequenceExitPolicy";
import {
  BroadcastProHeadlineSecondary,
  BroadcastProHeadlineTitle,
  getBroadcastProHeaderSecondaryLine,
  shouldHideBroadcastProHeaderSecondary,
} from "./headline";
import { DEFAULT_BROADCAST_PRO_HEADLINE_SIZING } from "../../../types/broadcast-pro/headline-lockup";

export const BroadcastProMainHeader = () => {
  const { layout, broadcastProHeadlineSizing } = useThemeContext();
  const { heights } = layout;
  const { club, metadata, data } = useVideoDataContext();
  const { animations } = useAnimationContext();
  const TextAnimations = animations.text.main;
  const LogoAnimations = animations.image.main.title.logo;

  const { timings } = data;

  const exitFrame = calculateMainHeaderExitFrame(timings);
  const crestPx =
    broadcastProHeadlineSizing?.headerOrgCrestPx ??
    DEFAULT_BROADCAST_PRO_HEADLINE_SIZING.headerOrgCrestPx;

  const hideSecondaryLine = shouldHideBroadcastProHeaderSecondary(
    metadata.compositionId,
  );
  const secondaryLine = hideSecondaryLine
    ? ""
    : getBroadcastProHeaderSecondaryLine(metadata, club.name);

  const OrgLogo = () => (
    <div
      className="mx-auto mb-2 shrink-0 overflow-hidden rounded-full bg-white p-2 shadow-xl"
      style={{ width: crestPx, height: crestPx }}
    >
      <div className="flex h-full w-full min-h-0 min-w-0 items-center justify-center overflow-hidden rounded-full">
        {club.logo?.url ? (
          <AnimatedImage
            src={club.logo.url}
            width="100%"
            height="100%"
            maxWidth="100%"
            maxHeight="100%"
            fit="contain"
            className="max-h-full max-w-full object-contain"
            animation={LogoAnimations.introIn}
            exitAnimation={LogoAnimations.introOut}
            exitFrame={exitFrame}
          />
        ) : null}
      </div>
    </div>
  );

  const titleBlock = (
    <BroadcastProHeadlineTitle
      text={metadata.title}
      variant="mainHeader"
      letterAnimation="none"
      animation={TextAnimations.title}
      exitAnimation={TextAnimations.copyOut}
      exitFrame={exitFrame}
    />
  );

  const headerProps = {
    height: heights.header,
    alignment: "center" as const,
    Logo: <OrgLogo />,
    Title: titleBlock,
  };

  if (hideSecondaryLine) {
    return <VerticalHeaderLogoTitle {...headerProps} Name={null} />;
  }

  return (
    <VerticalHeaderLogoTitleName
      {...headerProps}
      Name={
        <BroadcastProHeadlineSecondary
          text={secondaryLine}
          variant="mainHeader"
          animation={TextAnimations.title}
          exitAnimation={TextAnimations.copyOut}
          exitFrame={exitFrame}
        />
      }
    />
  );
};
